import express from "express";
import path from "path";
import fs from "fs";
import { createServer as createViteServer } from "vite";

interface User {
  id: string;
  name: string;
  email: string;
  createdAt: string;
}

interface ScoreEntry {
  id: string;
  levelId: string;
  levelName: string;
  userId: string;
  userName: string;
  userEmail?: string;
  timeMs: number;
  moves: number;
  itemsUsed: number;
  date: string;
}

interface Database {
  users: User[];
  scores: ScoreEntry[];
}

const DB_FILE = path.join(process.cwd(), "data", "db.json");

function loadDb(): Database {
  try {
    if (fs.existsSync(DB_FILE)) {
      const data = fs.readFileSync(DB_FILE, "utf-8");
      return JSON.parse(data);
    }
  } catch (err) {
    console.error("Error reading db.json:", err);
  }
  return { users: [], scores: [] };
}

function saveDb(db: Database) {
  try {
    const dir = path.dirname(DB_FILE);
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }
    fs.writeFileSync(DB_FILE, JSON.stringify(db, null, 2), "utf-8");
  } catch (err) {
    console.error("Error writing db.json:", err);
  }
}

async function startServer() {
  const app = express();
  const PORT = 3000;

  app.use(express.json());

  // API Health
  app.get("/api/health", (_req, res) => {
    res.json({ status: "ok", timestamp: new Date().toISOString() });
  });

  // User Signup
  // Requires: name and email only
  app.post("/api/auth/signup", (req, res) => {
    const { name, email } = req.body;
    if (!name || !email || typeof name !== "string" || typeof email !== "string") {
      res.status(400).json({ error: "Name and email are required to register." });
      return;
    }

    const cleanEmail = email.trim().toLowerCase();
    const cleanName = name.trim();

    if (!cleanEmail.includes("@") || cleanEmail.length < 5) {
      res.status(400).json({ error: "Please provide a valid email address." });
      return;
    }

    const db = loadDb();
    let existingUser = db.users.find((u) => u.email.toLowerCase() === cleanEmail);

    if (existingUser) {
      // Update name if changed
      existingUser.name = cleanName;
      saveDb(db);
      res.json({ user: existingUser, message: "Welcome back!" });
      return;
    }

    const newUser: User = {
      id: "u-" + Date.now().toString(36) + Math.random().toString(36).substring(2, 6),
      name: cleanName,
      email: cleanEmail,
      createdAt: new Date().toISOString(),
    };

    db.users.push(newUser);
    saveDb(db);

    res.json({ user: newUser, message: "Registration successful!" });
  });

  // Get current user profile
  app.get("/api/auth/me", (req, res) => {
    const userId = req.query.userId as string;
    if (!userId) {
      res.status(400).json({ error: "userId parameter is required." });
      return;
    }

    const db = loadDb();
    const user = db.users.find((u) => u.id === userId);
    if (!user) {
      res.status(404).json({ error: "User not found." });
      return;
    }

    res.json({ user });
  });

  // Today's Daily Challenge info
  app.get("/api/daily-challenge", (_req, res) => {
    const today = new Date().toISOString().split("T")[0];
    res.json({
      date: today,
      challengeId: `daily-${today}`,
      name: `Daily Challenge — ${today}`,
      rules: "Illuminate all optical sensors in the minimum time. One global puzzle per day.",
    });
  });

  // Leaderboard endpoint
  app.get("/api/leaderboard", (req, res) => {
    const levelId = (req.query.levelId as string) || `daily-${new Date().toISOString().split("T")[0]}`;
    const limit = parseInt((req.query.limit as string) || "50", 10);

    const db = loadDb();
    const filtered = db.scores
      .filter((s) => s.levelId === levelId)
      .sort((a, b) => {
        // Sort by timeMs ascending (fastest first), then moves
        if (a.timeMs !== b.timeMs) return a.timeMs - b.timeMs;
        return a.moves - b.moves;
      });

    const ranked = filtered.slice(0, limit).map((entry, index) => ({
      ...entry,
      rank: index + 1,
    }));

    res.json({
      levelId,
      totalEntries: filtered.length,
      leaderboard: ranked,
    });
  });

  // Score submission
  // Players who are not signed up must signup to submit to the leaderboard
  app.post("/api/scores/submit", (req, res) => {
    const {
      levelId,
      levelName,
      userId,
      userName,
      userEmail,
      timeMs,
      moves,
      itemsUsed,
    } = req.body;

    if (!levelId || typeof timeMs !== "number" || typeof moves !== "number") {
      res.status(400).json({ error: "Invalid submission data." });
      return;
    }

    // Check if user is registered
    const db = loadDb();
    let user = db.users.find((u) => u.id === userId);

    if (!user && userEmail && userName) {
      // Auto-signup if name and email provided
      user = {
        id: "u-" + Date.now().toString(36) + Math.random().toString(36).substring(2, 6),
        name: userName.trim(),
        email: userEmail.trim().toLowerCase(),
        createdAt: new Date().toISOString(),
      };
      db.users.push(user);
    }

    if (!user) {
      res.status(401).json({
        error: "Sign up is required to post scores to the public leaderboard. You can play anonymously or sign up with your name and email.",
        requiresSignup: true,
      });
      return;
    }

    // Check if user already submitted a score for this level
    const existingScoreIndex = db.scores.findIndex(
      (s) => s.levelId === levelId && s.userId === user!.id
    );

    let isNewBest = false;
    const newEntry: ScoreEntry = {
      id: "s-" + Date.now().toString(36) + Math.random().toString(36).substring(2, 6),
      levelId,
      levelName: levelName || levelId,
      userId: user.id,
      userName: user.name,
      timeMs,
      moves,
      itemsUsed: itemsUsed || 0,
      date: new Date().toISOString(),
    };

    if (existingScoreIndex >= 0) {
      const existing = db.scores[existingScoreIndex];
      // Keep best (fastest) time
      if (timeMs < existing.timeMs) {
        db.scores[existingScoreIndex] = newEntry;
        isNewBest = true;
      }
    } else {
      db.scores.push(newEntry);
      isNewBest = true;
    }

    saveDb(db);

    // Calculate user's current rank
    const ranked = db.scores
      .filter((s) => s.levelId === levelId)
      .sort((a, b) => a.timeMs - b.timeMs);
    const userRank = ranked.findIndex((s) => s.userId === user!.id) + 1;

    res.json({
      success: true,
      isNewBest,
      rank: userRank,
      totalEntries: ranked.length,
      entry: newEntry,
    });
  });

  // Vite middleware setup
  if (process.env.NODE_ENV !== "production") {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "spa",
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), "dist");
    app.use(express.static(distPath));
    app.get("*", (_req, res) => {
      res.sendFile(path.join(distPath, "index.html"));
    });
  }

  app.listen(PORT, "0.0.0.0", () => {
    console.log(`Laser Mirrors Server running on http://0.0.0.0:${PORT}`);
  });
}

startServer();
